import React, { useState } from 'react';
import logo from '../Images/BNutritions Logo.png';
import '../App.css';
import { message, Spin } from 'antd';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { EyeOutlined, EyeInvisibleOutlined } from '@ant-design/icons';
import { Input } from 'antd';

function Login ({onLogin}) {
  const [userNameInput, setUserNameInput] = useState(localStorage.getItem('user'));
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const toggleShowPassword = () => {setShowPassword(!showPassword)};

  const navigate = useNavigate();
  const passwordIcon = showPassword ? <EyeOutlined onClick={toggleShowPassword} /> : <EyeInvisibleOutlined onClick={toggleShowPassword} />;

  const checkUserDetails = (event) => {
    setLoading(true);
    event.preventDefault();
      if(userNameInput.trim() === '' || password === ''){
        setTimeout(() => {
          message.info("Please Enter User Name and Password")
        })
      }else{
        const ecodedPassw = encodeURIComponent(password)
    axios.get(`https://orders.baleenmedia.com/API/Wellness/Login.php/get?JsonUserName=${userNameInput.trim()}&JsonPassword=${ecodedPassw}`)
    .then(response => {
      return response;
    })
      .then(data => { 
        setLoading(false);
        //setResp(data);
        if(data.data === 'Login Succesfully'){
          localStorage.setItem('user', userNameInput.trim())
          onLogin(userNameInput.trim());
          navigate('/')
          //navigation.navigate('Main', { userNameInput });
          
        }else{
          setTimeout(() => {
            message.error("Invalid Credentials")
          })
        }
    })
      .catch(error => {
        console.error(error);
      });
  };}

  const MovetoPasswordPage = (event) => {
    event.preventDefault();
    navigate('/ChangePassword');
  }

  const handleChange = (e) => {
      setUserNameInput(e.target.value.trim());
  }

  return (
    <div className='main'>   
      <div className='sub-main'>
        <form>    
        <div className='imgs'>   
          <div className='container-image'>
            <img src = {logo} className = 'profile' alt = 'profile' />
          </div>
        </div>
        <div>
          <div>
            <input 
          // style={styles.input}
            id='userNameInput'
            className='input-physical'
            value={userNameInput}
            placeholder = "User Name"
            onChange={handleChange}
            // maxLength = {12}
            />
          </div>
          <div className="second-input">
            <Input.Password
            // style={styles.input}
            style={{
              padding: '10px',
              border: '2px solid #ccc',
              borderRadius: '10px',
              fontSize: '16px',
              fontFamily: "'Poppins', sans-serif",
              borderColor: '#2ea93f',
              borderWidth: '2px',
              width: '240px'
            }}
              defaultValue={password}
              placeholder = "Password"
              type={showPassword ? "text" : "password"}
              onChange={e => setPassword(e.target.value)}
            // maxLength = {12}
            iconRender={() => passwordIcon}
            />
          </div>
          <div>
            <button type="submit" onClick={checkUserDetails} className='login-button'>Login</button>
          </div>
          <div>
            <h6 className='signup-label'>Need a stronger password? <br></br> Click here to<span><button name='create-account-btn' onClick = {MovetoPasswordPage}>change!</button></span></h6>
          </div>
          <div>
            <h5 className='normal-label'>Version: 2.2.5 </h5>
          </div>
          {loading && 
            <div className='load-container'>
              <Spin />
            </div>
          }
          </div>
        </form>
      </div>
    </div>
  );
}

export default Login;