import React, {useState, useEffect} from "react";
import '../App.css';
import { Input, message } from 'antd';
import { EyeOutlined, EyeInvisibleOutlined } from '@ant-design/icons';
import { api } from "../API/FetchAllDetailsAPI";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const ChangePassword = () => {
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword,setShowPassword] = useState(false);
    const [password, setPassword] = useState('');
    const toggleShowPassword = () => {setShowPassword(!showPassword)};
    const navigate = useNavigate()
    const passwordIcon = showPassword ? <EyeOutlined onClick={toggleShowPassword} /> : <EyeInvisibleOutlined onClick={toggleShowPassword} />;

    const FetchPassword = async() => {
        try{
            const response = await api.get("/Get&EditUserPassword.php/get", {
                params: {
                    JsonUserName: localStorage.getItem('user')
                }
            })
            setPassword(response.data);
        }catch(error){
            console.error('Error fetching data', error);
        }
    }

    useEffect(() => {FetchPassword()}, [])

    const authorizePassword = async(event) => {
        event.preventDefault()
        if (currentPassword.trim() === ''|| newPassword.trim() === '' || confirmPassword.trim() === ''){
            setTimeout(() => {
                message.error("Please fill the fields.")
            })
        } else{
            if(password === currentPassword){
                if(password !== newPassword){
                    if(newPassword === confirmPassword){
                        const encodedPassw = encodeURIComponent(newPassword)
                        await axios.get(`https://orders.baleenmedia.com/API/Wellness/Get&EditUserPassword.php/get?JsonUserName=${localStorage.getItem('user')}&JsonNewPassword=${encodedPassw}`)
                        .then((response) => {
                            if(response.data === "Updated Successfully!") {
                                setTimeout(() => {
                                    message.success("Password updated Successfully!");
                                });
                                setPassword(newPassword)
                                setNewPassword('')
                                setCurrentPassword('')
                                setConfirmPassword('')
                                navigate('/login')
                            } else {
                                setTimeout(() => {
                                    message.error("Problem in Changing Password!");
                                });
                            }}) 
                    }else {
                        setTimeout(() => {
                            message.error("Passwords do not match")
                        })
                    }
                } else {
                    setTimeout(() => {
                        message.error("Password should be different from the previous one")
                    })
                    }
                }else {
                    setTimeout(() => {
                        message.error("Please enter current password correctly.")
                    })
                }
            } 
        
    }

    const styles = {
        padding: '10px',
        border: '2px solid #ccc',
        borderRadius: '10px',
        fontSize: '16px',
        fontFamily: "'Poppins', sans-serif",
        borderColor: '#2ea93f',
        borderWidth: '2px',
        width: '240px'
      }

    return(
        <div className='main'>   
          <div className='sub-main'>
            <form>
                <h6 className="normal-label">Password change for {localStorage.getItem('user')}</h6>
                <Input.Password 
                    className="Signup-Input"
                    name='CurrentPassword' 
                    defaultValue={currentPassword}
                    placeholder = "Current Password"
                    type={showPassword ? "text" : "password"}
                    onChange={e => setCurrentPassword(e.target.value)}
                    iconRender={() => passwordIcon}
                    style = {styles}
                />
                <Input.Password  
                    className="Signup-Input"
                    name='NewPassword*'
                    defaultValue={newPassword}
                    placeholder = "New Password"
                    type={showPassword ? "text" : "password"}
                    onChange={e => setNewPassword(e.target.value)}
                    iconRender={() => passwordIcon}
                    style = {styles}
                />
                <Input.Password 
                    className="Signup-Input"
                    name='ConfirmPassword'
                    defaultValue={confirmPassword}
                    placeholder = "Confirm Password"
                    type={showPassword ? "text" : "password"}
                    onChange={e => setConfirmPassword(e.target.value)}
                    iconRender={() => passwordIcon}
                    style = {styles}
                />
                <div>
            <button type="submit" className='login-button' onClick={authorizePassword}>Confirm</button>
          </div>
            </form>
        </div>
    </div>
    )
}

export default ChangePassword;